/// <summary>
///     The <c>AVAsmmContactPersonFrm_Extension</c> class is the extension for <c>smmContactPerson</c>
/// </summary>
[ExtensionOf(FormStr(smmContactPerson))]
final class AVAsmmContactPersonFrm_Extension
{
    public  DirPartyType    allowedParentType;
    public  DirPartyType    allowedChildType;

}

Method.Source:
/// <summary>
///    AVA <c>getAllowedChildType</c> method.
/// </summary>
/// <returns>
///    <c>DirPartyType</c> as return value
/// </returns>
public DirPartyType getAllowedChildType()
{
    return allowedChildType;
}

/// <summary>
///    AVA <c>getAllowedParentType</c> method.
/// </summary>
/// <returns>
///    <c>DirPartyType</c> as return value
/// </returns>
public DirPartyType getAllowedParentType()
{
    return allowedParentType;
}

/// <summary>
///    AVA <c>getAllowedPartyTypes</c> method.
/// </summary>
void getAllowedPartyTypes()
{
    if (dirPartyRelationship.RelationshipTypeId != dirRelationshipTypeTable.RelationshipTypeId)
    {
        dirRelationshipTypeTable.data(DirRelationshipTypeTable::find(dirPartyRelationship.RelationshipTypeId));
    }
    [allowedParentType, allowedChildType] = [dirRelationshipTypeTable.ParentPartyType, dirRelationshipTypeTable.ChildPartyType];
}

/// <summary>
///    AVA <c>updateRange</c> method.
/// </summary>
/// <param name="_dataSource">
///    <c>FormDataSource</c> as type
/// </param>
public void updateRange(FormDataSource _dataSource)
{
    QueryBuildDataSource    qbd;
    QueryBuildRange         qbRange;
    str                     qStr;

    qbd = _dataSource.query().dataSourceTable(tableNum(DirPartyRelationship));
    qStr = strFmt(  '((%1.%2 == %4) || (%1.%3 == %4))',
                    qbd.name(), fieldStr(DirPartyRelationship, ParentParty),
                    fieldStr(DirPartyRelationship,ChildParty), dirPartyTable.RecId);

    qbRange = SysQuery::findOrCreateRange(qbd, fieldNum(DirPartyRelationship, RecId));
    qbRange.status(RangeStatus::Locked);
    qbRange.value(qStr);
}

/// <summary>
///     AVA <c>init</c> method.
/// </summary>
void init()
{
    next init();

    this.avaCheckUnrelatedContacts();
}

/// <summary>
///     AVA <c>avaCheckUnrelatedContacts</c> method.
/// </summary>
void avaCheckUnrelatedContacts()
{
    Args                    locArgs;
    Args                    locArgsService;
    //MenuFunction            locMenuFunction;

    locArgs = this.args();

    if(locArgs && locArgs.record())
    {
        if(     locArgs.record().TableId    == tableNum(smmBusRelTable)
            &&  locArgs.menuItemType()      == MenuItemType::Display
            &&  locArgs.menuItemName()      == menuItemDisplayStr(smmContactsListPage)  )
        {
            locArgsService = new Args();
            locArgsService = locArgs;
            locArgsService.menuItemType(MenuItemType::Action);
            locArgsService.menuItemName(menuItemActionStr(AVACreateContactPersonBasedOnGABBusRel));
            /*
            locMenuFunction = new MenuFunction(menuItemActionStr(AVACreateContactPersonBasedOnGABBusRel), MenuItemType::Action);
            locMenuFunction.run(locArgsService);
            */

            AVACreateContactPersonBasedOnGABController::main(locArgsService);
            /*
                info("@NDX:NXAMissingContactsFoundAndCreated");
            */
        }
    }
